#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        // x>0, y>0, x+y<n
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x,y});
    };

    for(int k=0; k<n-1; k++){
        int pos = -1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;

        int remaining = n - k; // elements in p[k..n-1]
        if(remaining <= 2){
            // Only 2 elements left and they're swapped - but we can't do x+y < n with just these
            // Actually remaining=2 means k=n-2, and if p[k]!=k+1 then p[k]=n, p[n-1]=n-1
            // This shouldn't happen if we placed everything else correctly
            // Actually it can't: if 1..n-2 are placed, positions n-2 and n-1 must be n-1 and n, so if p[n-2]!=n-1 then impossible? 
            // The permutation is valid so this case means the last two are swapped, but we need an op.
            // x=1,y=1 requires n>2. n-2=k, so n>=3 means remaining>=2 is fine if n>=3
            // For n=2: only one possible wrong state [2,1], x=1,y=1 requires x+y<2 fails. But n=2 identity is only sorted.
            break; // last element falls into place
        }

        // Move target from pos to position k
        // Step 1: bring target to position n-1
        if(pos < n-1){
            int x1 = pos + 1; // prefix = p[0..pos]
            int y1 = n - 1 - pos; // suffix = p[pos+1..n-1]
            // x1 + y1 = n, need < n. So adjust:
            // Use x=pos, y=n-1-pos if both > 0 and sum < n
            // After: [p[pos+1..n-1], p[pos..pos], p[0..pos-1]] -> target at position y1 = n-1-pos
            if(pos > 0 && (n-1-pos) > 0){
                doOp(pos, n-1-pos);
                pos = n-1-pos; // target now here
            }
            if(pos < n-1 && pos > 0){
                doOp(pos, n-1-pos);
                pos = n-1-pos;
            }
            if(pos == 0 && n > 2){
                doOp(1, n-2);
                pos = n-1;
            }
        }
        // Step 2: target at n-1, move to k
        if(pos == n-1 && k < n-1){
            int y2 = n - 1 - k; // >= 1
            int x2 = 1;
            if(x2 + y2 < n){
                doOp(1, n-1-k);
                // target was at n-1, in suffix, goes to position (n-1-k)-1 - ... 
                // suffix = p[k+1..n-1], moved to front. target at end of suffix = position y2-1 = n-2-k
                // Hmm, that's not k. Let me use x=k+1, y=1
                // Actually let me recompute after last op...
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
